const $=id=>document.getElementById(id),order=Object.keys(topics);let ready=false,started=false,current=null,selected=null,textOpen=false,light='gold',returnFocus=null;
function progress(value){$('loading-number').textContent=value+'%';$('loading-fill').style.width=value+'%';$('loading-message').textContent=value<38?'Preparando sua jornada…':value<68?'Cultivando o bosque…':value<100?'Acendendo as luzes…':'Bosque pronto. Seu caminho começa aqui.';}
window.addEventListener('forest-progress',e=>progress(e.detail));
window.addEventListener('forest-ready',()=>{ready=true;document.body.dataset.ready='true';progress(100);$('start').disabled=false;$('start-label').textContent='Começar jornada';$('loading-line').classList.add('complete');});
window.addEventListener('forest-error',()=>{ready=false;$('start').disabled=true;$('start-label').textContent='Bosque indisponível';$('loading-message').textContent='Você pode conhecer todo o portfólio pela versão em texto.';$('loading-number').textContent='';});
function startJourney(){if(!ready)return;started=true;document.body.classList.add('exploring');$('intro').hidden=true;$('journey').hidden=false;$('footer-right').textContent='ESCOLHA UM DESTINO OU EXPLORE LIVREMENTE';window.Forest.allowManual(true);document.querySelector('[data-topic="about"]').focus();}
function closeReader(){document.body.classList.remove('reading');$('reader').hidden=true;window.Forest?.allowManual(started&&!textOpen);}
function chooseTopic(id){if(!topics[id])return;selected=id;document.querySelectorAll('[data-topic]').forEach(b=>b.setAttribute('aria-current',String(b.dataset.topic===id)));closeReader();$('controls-help').hidden=true;$('help-toggle').setAttribute('aria-expanded','false');const t=topics[id];$('location-kicker').textContent=`DESTINO ${t.number} / 06`;$('location-title').textContent=t.place;$('location-copy').textContent=t.label;if(!ready){showTopic(id);return;}$('travel-label').textContent=`A caminho: ${t.place.toLowerCase()}`;$('travel-fill').style.width='0%';$('travel').hidden=false;document.body.classList.add('traveling');window.Forest.go(id);}
function showTopic(id){current=id;selected=id;const t=topics[id];$('travel').hidden=true;document.body.classList.remove('traveling');$('reader-kicker').textContent=`${t.number} / 06 · ${t.label.toUpperCase()}`;$('reader-title').innerHTML=t.title;$('reader-content').innerHTML=`<p class="read-only-caption">${t.intro}</p>${t.html}`;$('reader-place').textContent=t.place;$('reader').hidden=false;document.body.classList.add('reading');$('reader').querySelector('.reader-scroll').scrollTop=0;window.Forest?.allowManual(false);$('reader-title').focus({preventScroll:true});$('next-topic').innerHTML=id==='contact'?'Voltar à origem <span aria-hidden="true">↗</span>':'Próximo caminho <span aria-hidden="true">→</span>';document.body.dataset.currentTopic=id;}
window.addEventListener('forest-arrive',e=>showTopic(e.detail.id));window.addEventListener('forest-travel',e=>{$('travel-fill').style.width=Math.round(e.detail.progress*100)+'%';});
$('start').addEventListener('click',startJourney);document.querySelectorAll('[data-topic]').forEach(b=>b.addEventListener('click',()=>chooseTopic(b.dataset.topic)));
$('close-reader').addEventListener('click',()=>{closeReader();document.querySelector(`[data-topic="${current||'about'}"]`).focus();});
$('next-topic').addEventListener('click',()=>chooseTopic(order[(order.indexOf(current)+1)%order.length]));
$('skip-travel').addEventListener('click',()=>window.Forest?.skip());
$('help-toggle').addEventListener('click',()=>{const open=$('controls-help').hidden;$('controls-help').hidden=!open;$('help-toggle').setAttribute('aria-expanded',String(open));});
$('light-toggle').addEventListener('click',()=>{light=light==='gold'?'mist':'gold';window.Forest?.setLight(light);$('light-toggle').innerHTML=light==='gold'?'☀ <span>Entardecer</span>':'☁ <span>Manhã</span>';$('light-toggle').setAttribute('aria-label',light==='gold'?'Trocar para luz da manhã':'Trocar para luz do entardecer');});
function openText(){returnFocus=document.activeElement;textOpen=true;window.Forest?.cancel();window.Forest?.allowManual(false);$('travel').hidden=true;$('direct-reading').hidden=false;$('direct-title').focus();document.body.classList.add('text-open');}
function closeText(){textOpen=false;$('direct-reading').hidden=true;document.body.classList.remove('text-open');window.Forest?.allowManual(started&&$('reader').hidden);returnFocus?.focus({preventScroll:true});}
$('direct-content').innerHTML=order.map(id=>{const t=topics[id];return `<section class="direct-section"><span class="eyebrow">${t.number} · ${t.label.toUpperCase()}</span><h2>${t.title.replace('<br>',' ')}</h2><p>${t.intro}</p>${t.html}</section>`;}).join('');
for(const id of ['text-mode','direct-intro'])$(id).addEventListener('click',openText);$('close-direct').addEventListener('click',closeText);document.querySelector('.skip-link').addEventListener('click',e=>{e.preventDefault();openText();});
$('home').addEventListener('click',e=>{e.preventDefault();window.Forest?.cancel();window.Forest?.allowManual(false);closeReader();started=false;current=null;selected=null;window.Forest?.allowManual(false);document.body.classList.remove('exploring','reading','traveling');$('intro').hidden=false;$('journey').hidden=true;$('travel').hidden=true;$('footer-right').textContent='CURIOSIDADE COMO PONTO DE PARTIDA';$('location-kicker').textContent='SEU PRÓXIMO DESTINO';$('location-title').textContent='Por onde começamos?';$('location-copy').textContent='Escolha um tema. Eu mostro o caminho.';document.querySelectorAll('[data-topic]').forEach(b=>b.removeAttribute('aria-current'));$('start').focus();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(textOpen){closeText();return;}if(!$('reader').hidden){closeReader();return;}if(document.body.classList.contains('traveling')){window.Forest?.cancel();$('travel').hidden=true;document.body.classList.remove('traveling');window.Forest?.allowManual(true);}}if(e.key==='Tab'&&textOpen){const focusable=Array.from($('direct-reading').querySelectorAll('a[href],button:not([disabled])')),first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}}});
window.addEventListener('error',e=>{if(e.target?.tagName==='SCRIPT'&&e.target.src.includes('scene'))window.dispatchEvent(new Event('forest-error'));},true);
progress(5);
